def filter_tasks(self, task_names, keep_dependencies=False):
        """If filter is applied only tasks with given name and its dependencies (if keep_keep_dependencies=True) are kept in the list of tasks."""
        new_tasks = {}
        for task_name in task_names:
            task = self.get_task(task_name)
            if task not in new_tasks:
                new_tasks[task.name] = task
            if keep_dependencies:
                for dependency in task.ordered_dependencies():
                    if dependency not in new_tasks:
                        new_tasks[dependency.name] = dependency
            else:
                #strip dependencies
                task.dependencies = set()

        self.tasks = new_tasks

def messages(fp, key='@message'):
    """
    Read lines of UTF-8 from the file-like object given in ``fp``, with the
    same fault-tolerance as :function:`tagalog.io.lines`, but instead yield
    dicts with the line data stored in the key given by ``key`` (default:
    "@message").
    """
    for line in lines(fp):
        txt = line.rstrip('\n')
        yield {key: txt}

def addTransitions(self, state, transitions):
        """
        Create a new L{TransitionTable} with all the same transitions as this
        L{TransitionTable} plus a number of new transitions.

        @param state: The state for which the new transitions are defined.
        @param transitions: A L{dict} mapping inputs to output, nextState
            pairs.  Each item from this L{dict} will define a new transition in
            C{state}.

        @return: The newly created L{TransitionTable}.
        """
        table = self._copy()
        state = table.table.setdefault(state, {})
        for (input, (output, nextState)) in transitions.items():
            state[input] = Transition(output, nextState)
        return table

